package com.intermarche.e2e.engine.replenishment;
import com.intermarche.backoffice.auth.DemoDataInitializer;
import com.intermarche.backoffice.domain.store.*;import com.intermarche.backoffice.domain.stock.*;import com.intermarche.backoffice.domain.wms.handling.ReplenishmentOrder;
import com.intermarche.backoffice.domain.util.DateTimeProvider;import com.intermarche.backoffice.engine.replenishment.*;import com.intermarche.backoffice.engine.stock.TemporalStockService;
import io.quarkus.test.TestTransaction;import io.quarkus.test.junit.QuarkusTest;import io.quarkus.test.security.TestSecurity;import jakarta.inject.Inject;import org.junit.jupiter.api.Test;
import java.util.*;import java.math.BigDecimal;import static org.junit.jupiter.api.Assertions.*;
@io.quarkus.test.junit.TestProfile(StockTransferWorkflowTest.Isolated.class)
@QuarkusTest @TestTransaction @TestSecurity(user="100234",roles="MANAGER")
class StockTransferWorkflowTest {
 public static class Isolated implements io.quarkus.test.junit.QuarkusTestProfile {public java.util.Map<String,String> getConfigOverrides(){return java.util.Map.of("quarkus.datasource.jdbc.url","jdbc:h2:mem:isolated_StockTransferWorkflowTest;DB_CLOSE_DELAY=-1","quarkus.scheduler.enabled","false","imomswms.demo-data.enabled","false","imomswms.embeddings.enabled","false");}}

 @io.quarkus.test.InjectMock com.intermarche.backoffice.auth.AuthenticationService authentication;
 @Inject DemoDataInitializer seed;@Inject StockTransferResource transfers;@Inject ReplenishmentResource replenishments;@Inject TemporalStockService stocks;
 Object create(StockTransferResource.Input r){try{return transfers.create(r);}catch(jakarta.ws.rs.WebApplicationException e){throw new AssertionError("Transfer failed: "+e.getResponse().getEntity(),e);}}
 StockTransferResource.Input input(boolean atomic){seed.seedDemoData();org.mockito.Mockito.when(authentication.getConnectedAccount()).thenReturn(Employee.findByBadgeId("100234"));var store=Store.findByCode("LYO-042");com.intermarche.backoffice.domain.workforce.BuildingTransit.delete("store",store);var sample=ReplenishmentOrder.<ReplenishmentOrder>find("code","REA-DEMO-RAY").firstResult().supplies.getFirst();var target=atomic?sample.source:sample.destination;
  if(atomic){var original=(ShelfLocation)org.hibernate.Hibernate.unproxy(sample.source);var shelf=new WarehouseShelfLocation();shelf.product=original.product;shelf.area=original.area;shelf.aisle=original.aisle;shelf.unit="TRF";shelf.elevation="1";shelf.position="1";shelf.locationCode="TRANSFER-TEST";shelf.persist();var building=BaseLocation.findBuildingsByLocations(List.of(sample.source)).getFirst();building.locations.add(shelf);target=shelf;}
  var r=new StockTransferResource.Input();r.storeId=store.id;r.requestKey=UUID.randomUUID().toString();r.mode=atomic?"SINGLE_GESTURE":"MISSION";r.start=DateTimeProvider.now();r.end=r.start.plusMinutes(30);var line=new ReplenishmentResource.Line();line.productId=sample.account.product.id;line.sourceLocationId=sample.source.id;line.destinationLocationId=target.id;line.quantity=BigDecimal.valueOf(4);r.lines=List.of(line);return r;
 }
 @SuppressWarnings("unchecked") @Test void aSingleGestureIsAtomicAndReplayingItDoesNotMoveStockTwice(){var r=input(true);var account=stocks.account(r.storeId,r.lines.getFirst().productId);var before=stocks.availability(account.id,null,DateTimeProvider.now()).physical;var result=(Map<String,Object>)create(r);assertEquals("DONE",result.get("status").toString());create(r);assertEquals(0,before.compareTo(stocks.availability(account.id,null,DateTimeProvider.now()).physical));assertEquals(0,BigDecimal.valueOf(4).compareTo(StockMovement.getEntityManager().createQuery("select coalesce(sum(m.quantity),0) from StockMovement m where m.account=?1 and m.location.id=?2",BigDecimal.class).setParameter(1,account).setParameter(2,r.lines.getFirst().destinationLocationId).getSingleResult()));}
 @SuppressWarnings("unchecked") @Test void partialReceptionKeepsTheRemainingQuantityInTransitAndIdentity(){var r=input(false);var account=stocks.account(r.storeId,r.lines.getFirst().productId);var before=stocks.availability(account.id,null,DateTimeProvider.now()).physical;long id=((Number)((Map<String,Object>)create(r)).get("id")).longValue();var order=ReplenishmentOrder.<ReplenishmentOrder>findById(id);var supply=order.supplies.getFirst();replenishments.start(id,r.storeId);var receipt=new ReplenishmentResource.Receipt();receipt.storeId=r.storeId;receipt.eventKey=UUID.randomUUID().toString();var line=new ReplenishmentResource.ReceiptLine();line.supplyId=supply.id;line.quantity=BigDecimal.valueOf(4);receipt.lines=List.of(line);replenishments.pick(id,receipt);receipt.eventKey=UUID.randomUUID().toString();line.quantity=BigDecimal.ONE;replenishments.receive(id,receipt);replenishments.receive(id,receipt);assertEquals(0,BigDecimal.valueOf(3).compareTo(supply.pickedQuantity().subtract(supply.received)));assertEquals(0,before.compareTo(stocks.availability(account.id,null,DateTimeProvider.now()).physical));assertEquals(1,SupplyStockAllocation.count("supply",supply));}
}
